'use client';

import { useEffect, useState } from 'react';
import dynamic from 'next/dynamic';

const WordLikeEditor = dynamic(() => import('@/components/editor/WordLikeEditor'), { ssr: false });

const STRAPI_URL = process.env.NEXT_PUBLIC_STRAPI_URL || 'http://localhost:1337';

interface UploadedFile {
  id: number;
  url: string;
}

interface ResearchTransfer {
  id: number;
  documentId: string;
  title: string;
  slug: string;
  summary?: string | null;
  content?: string | null;
  attachments?: Array<{
    id: number;
    name: string;
    url: string;
    ext: string;
    size: number;
  }> | null;
  publish_time?: string | null;
  is_active: boolean;
  is_top: boolean;
  sort_order: number;
}

interface StrapiResponse {
  data: Array<{
    id: number;
    documentId: string;
    title: string;
    slug: string;
    summary?: string | null;
    content?: string | null;
    attachments?: Array<{
      id: number;
      name: string;
      url: string;
      ext: string;
      size: number;
    }> | null;
    publish_time?: string | null;
    is_active: boolean;
    is_top: boolean;
    sort_order: number;
  }>;
}

interface FormDataType {
  title: string;
  slug: string;
  summary: string;
  content: string;
  publish_time: string;
  is_active: boolean;
  is_top: boolean;
  sort_order: number;
}

export default function ResearchTransfersManagement() {
  const [transfers, setTransfers] = useState<ResearchTransfer[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editingTransfer, setEditingTransfer] = useState<ResearchTransfer | null>(null);
  const [formData, setFormData] = useState<FormDataType>({
    title: '',
    slug: '',
    summary: '',
    content: '',
    publish_time: new Date().toISOString().slice(0, 16),
    is_active: true,
    is_top: false,
    sort_order: 0,
  });
  const [attachmentFiles, setAttachmentFiles] = useState<File[]>([]);

  useEffect(() => {
    fetchTransfers();
  }, []);

  const fetchTransfers = async () => {
    try {
      const response = await fetch(`${STRAPI_URL}/api/research-transfers?populate=attachments&sort[0]=is_top:desc&sort[1]=publish_time:desc`);
      const data: StrapiResponse = await response.json();
      setTransfers(data.data.map((item) => ({
        id: item.id,
        documentId: item.documentId,
        title: item.title,
        slug: item.slug,
        summary: item.summary,
        content: item.content,
        attachments: item.attachments,
        publish_time: item.publish_time,
        is_active: item.is_active,
        is_top: item.is_top,
        sort_order: item.sort_order,
      })));
    } catch (error) {
      console.error('获取成果转化列表失败:', error);
    } finally {
      setLoading(false);
    }
  };

  const uploadAttachments = async (files: File[]): Promise<number[]> => {
    try {
      const uploadFormData = new FormData();
      files.forEach(file => uploadFormData.append('files', file));
      const response = await fetch(`${STRAPI_URL}/api/upload`, {
        method: 'POST',
        body: uploadFormData,
      });
      if (response.ok) {
        const data: Array<{ id: number }> = await response.json();
        return data.map(item => item.id);
      }
      return [];
    } catch (error) {
      console.error('上传附件失败:', error);
      return [];
    }
  };

  const handleEditorUpload = async (file: File): Promise<string> => {
    const uploadFormData = new FormData();
    uploadFormData.append('files', file);
    const response = await fetch(`${STRAPI_URL}/api/upload`, {
      method: 'POST',
      body: uploadFormData,
    });
    if (!response.ok) throw new Error('图片上传失败');
    const data: UploadedFile[] = await response.json();
    const url = data[0]?.url || '';
    return url.startsWith('http') ? url : `${STRAPI_URL}${url}`;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    try {
      let attachmentIds = editingTransfer?.attachments?.map(a => a.id) || [];
      if (attachmentFiles.length > 0) {
        const newIds = await uploadAttachments(attachmentFiles);
        if (newIds.length === 0) {
          alert('附件上传失败，请重试');
          return;
        }
        attachmentIds = [...attachmentIds, ...newIds];
      }

      const payload = {
        data: {
          ...formData,
          ...(attachmentIds.length > 0 ? { attachments: attachmentIds } : {}),
        },
      };

      const url = editingTransfer
        ? `${STRAPI_URL}/api/research-transfers/${editingTransfer.documentId}`
        : `${STRAPI_URL}/api/research-transfers`;
      const method = editingTransfer ? 'PUT' : 'POST';

      const response = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });

      if (response.ok) {
        setShowModal(false);
        setEditingTransfer(null);
        setFormData({
          title: '',
          slug: '',
          summary: '',
          content: '',
          publish_time: new Date().toISOString().slice(0, 16),
          is_active: true,
          is_top: false,
          sort_order: 0,
        });
        setAttachmentFiles([]);
        fetchTransfers();
      } else {
        const errorData: { error?: { message?: string } } = await response.json();
        console.error('保存失败:', errorData);
        alert('保存失败，请重试');
      }
    } catch (error) {
      console.error('保存失败:', error);
      alert('保存失败，请重试');
    }
  };

  const handleEdit = (transfer: ResearchTransfer) => {
    setEditingTransfer(transfer);
    setFormData({
      title: transfer.title,
      slug: transfer.slug,
      summary: transfer.summary || '',
      content: transfer.content || '',
      publish_time: transfer.publish_time
        ? new Date(transfer.publish_time).toISOString().slice(0, 16)
        : new Date().toISOString().slice(0, 16),
      is_active: transfer.is_active,
      is_top: transfer.is_top,
      sort_order: transfer.sort_order,
    });
    setAttachmentFiles([]);
    setShowModal(true);
  };

  const handleDelete = async (documentId: string) => {
    if (!confirm('确定要删除这个成果转化吗？')) return;
    try {
      const response = await fetch(`${STRAPI_URL}/api/research-transfers/${documentId}`, {
        method: 'DELETE',
      });
      if (response.ok) {
        fetchTransfers();
      } else {
        const errorData: { error?: { message?: string } } = await response.json();
        console.error('删除失败:', errorData);
        alert('删除失败，请重试');
      }
    } catch (error) {
      console.error('删除失败:', error);
      alert('删除失败，请重试');
    }
  };

  const handleAdd = () => {
    setEditingTransfer(null);
    setFormData({
      title: '',
      slug: '',
      summary: '',
      content: '',
      publish_time: new Date().toISOString().slice(0, 16),
      is_active: true,
      is_top: false,
      sort_order: 0,
    });
    setAttachmentFiles([]);
    setShowModal(true);
  };

  const handleAttachmentChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setAttachmentFiles(Array.from(e.target.files || []));
  };

  const removeExistingAttachment = async (attachmentId: number) => {
    if (!editingTransfer) return;
    const updatedAttachments = editingTransfer.attachments
      ?.filter(a => a.id !== attachmentId)
      .map(a => a.id) || [];
    try {
      const response = await fetch(`${STRAPI_URL}/api/research-transfers/${editingTransfer.documentId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ data: { attachments: updatedAttachments } }),
      });
      if (response.ok) {
        fetchTransfers();
        const updatedTransfer = transfers.find(t => t.documentId === editingTransfer.documentId);
        if (updatedTransfer) setEditingTransfer(updatedTransfer);
      }
    } catch (error) {
      console.error('删除附件失败:', error);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-xl">加载中...</div>
      </div>
    );
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold text-gray-800">成果转化管理</h1>
        <button
          onClick={handleAdd}
          className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition-colors"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
          </svg>
          添加成果转化
        </button>
      </div>

      <div className="bg-white rounded-lg shadow overflow-hidden">
        <table className="min-w-full divide-y divide-gray-200">
          <thead className="bg-gray-50">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">标题</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Slug</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">发布时间</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">附件</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">状态</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">操作</th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {transfers.map((transfer) => (
              <tr key={transfer.documentId}>
                <td className="px-6 py-4 text-sm font-medium text-gray-900">
                  <div className="flex items-center gap-2">
                    {transfer.is_top && (
                      <span className="px-2 py-0.5 bg-red-100 text-red-600 text-xs rounded">置顶</span>
                    )}
                    <span className="line-clamp-1">{transfer.title}</span>
                  </div>
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{transfer.slug}</td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                  {transfer.publish_time ? new Date(transfer.publish_time).toLocaleDateString('zh-CN') : '-'}
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                  {transfer.attachments?.length || 0} 个
                </td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${transfer.is_active ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'}`}>
                    {transfer.is_active ? '启用' : '禁用'}
                  </span>
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm font-medium flex gap-2">
                  <button onClick={() => handleEdit(transfer)} className="text-blue-600 hover:text-blue-900" title="编辑">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
                    </svg>
                  </button>
                  <button onClick={() => handleDelete(transfer.documentId)} className="text-red-600 hover:text-red-900" title="删除">
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                    </svg>
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 overflow-y-auto">
          <div className="bg-white rounded-lg p-8 max-w-4xl w-full mx-4 my-8 max-h-[90vh] overflow-y-auto">
            <h2 className="text-2xl font-bold mb-6">
              {editingTransfer ? '编辑成果转化' : '添加成果转化'}
            </h2>
            <form onSubmit={handleSubmit}>
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">标题 *</label>
                  <input
                    type="text"
                    required
                    value={formData.title}
                    onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    placeholder="请输入标题"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Slug *</label>
                  <input
                    type="text"
                    required
                    value={formData.slug}
                    onChange={(e) => setFormData({ ...formData, slug: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    placeholder="例如：ai-achievement-2024"
                  />
                  <p className="text-xs text-gray-500 mt-1">用于 URL，只能包含小写字母、数字和连字符</p>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">摘要</label>
                  <textarea
                    value={formData.summary}
                    onChange={(e) => setFormData({ ...formData, summary: e.target.value })}
                    rows={3}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    placeholder="请输入摘要"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">内容</label>
                  <WordLikeEditor
                    value={formData.content}
                    onChange={(html) => setFormData({ ...formData, content: html })}
                    uploadImage={handleEditorUpload}
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">发布时间</label>
                  <input
                    type="datetime-local"
                    value={formData.publish_time}
                    onChange={(e) => setFormData({ ...formData, publish_time: e.target.value })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">附件</label>
                  <input
                    type="file"
                    multiple
                    onChange={handleAttachmentChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  />
                  <p className="text-xs text-gray-500 mt-1">可以选择多个文件</p>

                  {attachmentFiles.length > 0 && (
                    <div className="mt-2 space-y-1">
                      <p className="text-sm font-medium text-gray-700">待上传文件：</p>
                      {attachmentFiles.map((file, idx) => (
                        <div key={idx} className="text-sm text-gray-600 flex items-center gap-2">
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                          </svg>
                          {file.name} ({(file.size / 1024).toFixed(2)} KB)
                        </div>
                      ))}
                    </div>
                  )}

                  {editingTransfer?.attachments && editingTransfer.attachments.length > 0 && (
                    <div className="mt-3 space-y-2">
                      <p className="text-sm font-medium text-gray-700">已有附件：</p>
                      {editingTransfer.attachments.map((file) => (
                        <div key={file.id} className="flex items-center justify-between p-2 bg-gray-50 rounded">
                          <div className="flex items-center gap-2 text-sm text-gray-600">
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                            </svg>
                            {file.name}
                          </div>
                          <button
                            type="button"
                            onClick={() => removeExistingAttachment(file.id)}
                            className="text-red-600 hover:text-red-800"
                          >
                            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                            </svg>
                          </button>
                        </div>
                      ))}
                    </div>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">排序</label>
                  <input
                    type="number"
                    value={formData.sort_order}
                    onChange={(e) => setFormData({ ...formData, sort_order: parseInt(e.target.value) || 0 })}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    placeholder="数字越小越靠前"
                  />
                </div>

                <div className="flex items-center gap-4">
                  <div className="flex items-center">
                    <input
                      type="checkbox"
                      id="is_active"
                      checked={formData.is_active}
                      onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
                      className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
                    />
                    <label htmlFor="is_active" className="ml-2 text-sm text-gray-700">启用显示</label>
                  </div>
                  <div className="flex items-center">
                    <input
                      type="checkbox"
                      id="is_top"
                      checked={formData.is_top}
                      onChange={(e) => setFormData({ ...formData, is_top: e.target.checked })}
                      className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
                    />
                    <label htmlFor="is_top" className="ml-2 text-sm text-gray-700">置顶</label>
                  </div>
                </div>
              </div>

              <div className="flex justify-end gap-4 mt-6">
                <button
                  type="button"
                  onClick={() => { setShowModal(false); setEditingTransfer(null); }}
                  className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50 transition-colors"
                >
                  取消
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
                >
                  保存
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
